<main class="public-pet <?=$pet['is_lost']?'lost-mode':''?>">
<section class="pet-public-hero"><div class="pet-public-photo"><?php if($pet['main_photo_path']):?><img src="<?=asset($pet['main_photo_path'])?>" alt="<?=e($pet['name'])?>"><?php else:?><span>🐾</span><?php endif;?></div><div class="pet-public-copy"><?php if($pet['is_lost']):?><span class="status danger large">🚨 ESTOU PERDIDO(A)</span><?php else:?><span class="status success">💚 Perfil protegido</span><?php endif;?><h1>Oi, eu sou <?=e($pet['name'])?>.</h1><p class="pet-id">ID PetPass: <b><?=e($pet['public_id'])?></b></p><p><?=e($pet['temperament']?:'Sou muito amado(a) pela minha família.')?></p><?php if($lostCase):?><div class="emergency-note"><b>A família está procurando por mim.</b><p><?=e($lostCase['public_message']?:$lostCase['description'])?></p><?php if($lostCase['reward_cents']):?><strong>Recompensa: <?=money($lostCase['reward_cents'])?></strong><?php endif;?></div><?php endif;?></div></section>
<section class="public-actions"><?php if($contacts):$first=$contacts[0];?><a class="action-button call" href="tel:<?=e($first['phone'])?>">📞 Ligar para <?=e($first['name'])?></a><a class="action-button whatsapp" target="_blank" rel="noopener" href="https://wa.me/<?=e(preg_replace('/\D/','',$first['whatsapp']?:$first['phone']))?>">💬 WhatsApp</a><?php endif;?><button class="action-button locate" type="button" data-open-sighting>📍 Encontrei este pet</button></section>
<div class="public-content-grid"><section class="public-card"><h2>Como cuidar de mim agora</h2><p><?=nl2br(e($pet['approach_instructions']?:'Aproxime-se com calma e mantenha-me em um local seguro.'))?></p><?php if($pet['fears']):?><div class="info-line"><b>Tenho medo de:</b> <?=e($pet['fears'])?></div><?php endif;?><?php if($pet['favorite_things']):?><div class="info-line"><b>Gosto de:</b> <?=e($pet['favorite_things'])?></div><?php endif;?></section><section class="public-card"><h2>Informações importantes</h2><div class="info-list"><div><span>Espécie</span><b><?=e($pet['species_name']?:$pet['custom_species']?:'Não informada')?></b></div><div><span>Raça</span><b><?=e($pet['breed_name']?:$pet['custom_breed']?:'Sem raça informada')?></b></div><div><span>Cor</span><b><?=e($pet['color']?:'Não informada')?></b></div><div><span>Cidade</span><b><?=e($pet['city']?:'Não informada')?></b></div></div></section>
<?php if($pet['public_audio_path']):?><section class="public-card full"><h2>Uma mensagem da minha família</h2><audio controls src="<?=asset($pet['public_audio_path'])?>"></audio></section><?php endif;?>
<?php if($allergies||$medications):?><section class="public-card full emergency-health"><h2>⚕️ Atenção de saúde</h2><?php foreach($allergies as $item):?><p><b>Alergia:</b> <?=e($item['allergen'])?> — <?=e($item['notes'])?></p><?php endforeach;?><?php foreach($medications as $item):?><p><b>Medicação:</b> <?=e($item['name'])?> <?=e($item['dosage'])?> · <?=e($item['frequency'])?></p><?php endforeach;?></section><?php endif;?>
<?php if($media):?><section class="public-card full"><h2>Minha galeria</h2><div class="media-grid"><?php foreach($media as $item):?><?php if($item['media_type']==='PHOTO'):?><figure><img src="<?=asset($item['file_path'])?>" alt="<?=e($item['caption'])?>"><figcaption><?=e($item['caption'])?></figcaption></figure><?php elseif($item['media_type']==='AUDIO'):?><audio controls src="<?=asset($item['file_path'])?>"></audio><?php elseif($item['media_type']==='VIDEO'):?><video controls src="<?=asset($item['file_path'])?>"></video><?php endif;?><?php endforeach;?></div></section><?php endif;?></div>
<section class="trust-strip"><span>🛡 Dados públicos controlados pela família</span><span>🔳 Identificação QR/NFC</span><span>❤️ PetPass Rescue</span></section>
</main>
<div class="modal" data-sighting-modal hidden><div class="modal-card"><button class="modal-close" data-close-sighting>×</button><h2>Encontrei <?=e($pet['name'])?></h2><p>Envie localização, foto ou mensagem. Não precisa instalar nada.</p><form method="post" enctype="multipart/form-data" action="<?=url('/pet/'.$pet['public_id'].'/sighting')?>" data-sighting-form><?=csrf_field()?><div class="form-grid"><label>Seu nome<input name="name" placeholder="Opcional"></label><label>Telefone<input name="phone" inputmode="tel" placeholder="Opcional"></label><label class="full">Mensagem<textarea name="message" rows="4" placeholder="Onde você viu ou encontrou o pet?"></textarea></label><label class="full">Foto<input type="file" name="photo" accept="image/*" capture="environment"></label><input type="hidden" name="latitude"><input type="hidden" name="longitude"><label class="check full"><input type="checkbox" name="location_consent" value="1"> Autorizo enviar minha localização para ajudar no resgate.</label></div><button class="btn btn-primary btn-block" type="button" data-capture-location>Usar minha localização</button><button class="btn btn-danger btn-block" type="submit">Enviar aviso à família</button></form></div></div>
